import('./src/orbit.js').then(m => {
  const planets = require('./data/planets.json');
  // sanity: at J2000 each planet's heliocentric distance must be within [q, ad]
  for (const p of planets) {
    const pos = m.positionElliptic(p, 2451545);
    const r = Math.hypot(pos.x, pos.y, pos.z);
    const q = p.a*(1-p.e), ad = p.a*(1+p.e);
    const ok = r >= q-1e-6 && r <= ad+1e-6;
    console.log(p.name.padEnd(8), 'r=', r.toFixed(4), ok ? 'OK' : 'FAIL');
  }
  // Earth 6 months later should be ~opposite side, still ~1au
  const e = planets[2];
  const p2 = m.positionElliptic(e, 2451545+182.6);
  console.log('Earth+0.5yr r=', Math.hypot(p2.x,p2.y,p2.z).toFixed(4));
  // Halley: near tp (1986-02-09, jd 2446469.97) distance should be ~q=0.575
  const halley = {a:17.93,e:0.9679,q:0.575,i:162.19,om:59.1,w:112.24,ma:274.38,tp:2446469.97,per:27700,n:0.01298,epoch:2439875.5};
  const hp = m.positionElliptic(halley, 2446469.97);
  console.log('Halley @ perihelion r=', Math.hypot(hp.x,hp.y,hp.z).toFixed(3), '(expect ~0.575)');
  // hyperbolic comet
  const hyp = {e:1.0007,a:-2926,q:2.116,i:100.42,om:176.08,w:32.36,tp:2395817.73};
  const hy = m.positionHyperbolic(hyp, 2395817.73);
  console.log('HYP @ perihelion r=', Math.hypot(hy.x,hy.y,hy.z).toFixed(3), '(expect ~2.116)');
  const hy2 = m.positionHyperbolic(hyp, 2395817.73+3650);
  console.log('HYP +10yr r=', Math.hypot(hy2.x,hy2.y,hy2.z).toFixed(1));
  // parabolic
  const par = {e:1, q:0.43, i:71, om:330, w:261, tp:1667909.5};
  const pa = m.positionParabolic(par, 1667909.5);
  console.log('PAR @ perihelion r=', Math.hypot(pa.x,pa.y,pa.z).toFixed(3), '(expect ~0.43)');
  // jd round trip
  console.log('jd check', m.formatJd(2451545), m.dateToJd(m.jdToDate(2460600.5)).toFixed(4));
});
