  const jd = ev.jd;
  const pa = m.positionElliptic(apo, jd);
  const pe = m.positionElliptic(planets[2], jd);
  const d = Math.hypot(pa.x-pe.x, pa.y-pe.y, pa.z-pe.z);
  console.log('computed separation at that jd:', d.toFixed(5), 'au =', (d/0.002569).toFixed(2), 'LD');
});
